function nextLesson(){return LESSONS.findIndex((_,i)=>!progress.lessons[LESSONS[i].id])<0?LESSONS.length-1:LESSONS.findIndex((_,i)=>!progress.lessons[LESSONS[i].id]);}
function startLesson(index,options={}){fallenWing=null;lookYaw=0;lookPitch=.34;lastDiscovery='';if(started)storeRecord();audio.unlock();session=new Session(index,{assist:progress.assist!==false,...options});started=true;view='play';cameraReady=false;lessonTipTimer=9;$('trim').value=0;$('play-hud').classList.remove('hidden');closeModal();updateUI();toast(options.free?'The bay is yours. Follow the gold gates or find your own line.':LESSONS[index].brief,7);}
function lessonChart(){view='chart';modal(`<span class="eyebrow">Foil Academy courses</span><h2 id="modal-title">Learn the moves.<br>Find your flow.</h2><p>Follow the lessons in order, or choose a skill you want to practice. Every lesson is open.</p><button class="location-banner" id="course-location"><span><small>LOCATION FOR ALL COURSES</small><b>${currentLocation.name}</b></span><span>Change ↗</span></button><div class="lesson-grid">${LESSONS.map((l,i)=>`<button class="lesson-option ${i===nextLesson()?'active':''}" data-lesson="${i}"><small>${String(i+1).padStart(2,'0')} · ${l.stage}</small><strong>${l.name}</strong><em class="lesson-goal">${l.goals.map(g=>g.goal+(g.unit?' '+g.unit:'')+' · '+g.label).join(' / ')}</em><span class="stars">${progress.lessons[l.id]?'★'.repeat(progress.lessons[l.id].stars)+'☆'.repeat(3-progress.lessons[l.id].stars):'○ ○ ○'}</span></button>`).join('')}<button class="lesson-option free-course" id="chart-free"><small>YOUR WATER · YOUR PACE</small><strong>Free Foiling</strong><em class="lesson-goal">Choose a location and conditions. Explore, practice, or chase your longest flight.</em><span class="stars">∞</span></button></div><div class="modal-actions"><button class="secondary-button" id="chart-back">${started?'Back to the water':'Back'}</button></div><p class="note">${Object.keys(progress.lessons).length}/${LESSONS.length} completed · Longest flight ${Number(progress.bestFlight||0).toFixed(1)}s · ${Object.keys(progress.legacyLessons).length?'Your previous course stars are archived; these new goals start fresh. ':''}${storageOK?'Progress saves on this browser.':'Browser storage is unavailable; progress lasts for this visit.'}</p>`,true);document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(Number(b.dataset.lesson)));$('chart-free').onclick=freeSetup;$('course-location').onclick=()=>locationMenu('chart');$('chart-back').onclick=()=>started?closeModal():welcome();}
const conditionFields=[
 {key:'wind',label:'Wind speed',min:0,max:28,step:.5,scale:1.94384,unit:'kn',hint:'14–18 knots is a friendly learning breeze.'},
 {key:'windFrom',label:'Wind from',min:0,max:357.5,step:2.5,scale:-180/Math.PI,unit:'bearing',hint:'The compass and wing load follow this direction.'},
 {key:'swell',label:'Wave height',min:0,max:1.2,step:.05,scale:2,unit:'m',hint:'Approximate crest to trough. Try 0.10–0.20 m for small waves.'},
 {key:'waveLength',label:'Wave spacing',min:4,max:80,step:1,scale:1,unit:'length',hint:'4–10 m creates busy bay chop. Longer spacing makes slower rolling swell.'},
 {key:'chop',label:'Choppiness',min:0,max:100,step:1,scale:100,unit:'%',hint:'Mix crossing wavelets for varied peaks instead of even rows.'},
 {key:'waveDirection',label:'Waves travel toward',min:0,max:355,step:5,scale:-180/Math.PI,unit:'bearing',hint:'Choose a following, head-on or cross swell independently of wind.'},
 {key:'gust',label:'Gusts & lulls',min:0,max:35,step:1,scale:100,unit:'%',hint:'0% is steady; higher values bring stronger changes.'},
 {key:'cloud',label:'Cloud cover',min:0,max:100,step:1,scale:100,unit:'%',hint:'Clear skies through to a soft, overcast day.'},
 {key:'sun',label:'Sunlight',min:0,max:100,step:1,scale:100,unit:'%',hint:'Direct sunshine, softened by your cloud cover.'}
];
const weatherPresets=[
 {name:'Easy breeze',detail:'Sunny · small ripples',wind:8.2,swell:.045,gust:.025,cloud:.16,sun:1,waveLength:35,chop:.18,waveDirection:Math.PI},
 {name:'Lively ripples',detail:'Small · quick · varied',wind:8.2,swell:.08,gust:.09,cloud:.22,sun:1,waveLength:18,chop:.85,waveDirection:Math.PI},
 {name:'Rolling swell',detail:'Long · flowing · open water',wind:9.3,swell:.30,gust:.16,cloud:.32,sun:.95,waveLength:65,chop:.12,waveDirection:Math.PI},
 {name:'Overcast',detail:'Soft light · gentle chop',wind:8.2,swell:.18,gust:.10,cloud:.94,sun:.65,waveLength:28,chop:.55,waveDirection:Math.PI},
 {name:'Bay chop',detail:'Short · steep · crossed',wind:9.2,swell:.12,gust:.20,cloud:.48,sun:.85,waveLength:6,chop:1,waveDirection:Math.PI*.75},
 {name:'Glass calm',detail:'Quiet water · explore',wind:0,swell:0,gust:0,cloud:.06,sun:.85,waveLength:35,chop:0,waveDirection:Math.PI}
];
function conditionsMenu(launch=false){
 view=launch?'free':'conditions';
 let otherFoilers=progress.otherFoilers,expertRatio=progress.expertRatio;
 let draft=launch?{wind:8.2,swell:.08,gust:.09,windFrom:currentLocation.windFrom??0,cloud:.22,sun:1,waveLength:18,chop:.85,waveDirection:wrap((currentLocation.windFrom??0)+Math.PI)}:{...session.config};
 modal(`<span class="eyebrow">WIND, WATER & LIGHT</span><h2 id="modal-title">Make the bay yours.</h2><p>${launch?'Choose a practice day and explore at your own pace.':'Sailing is paused. Adjust the day, then pick up where you left off.'}</p>
 ${launch?`<label class="location-setting">Location<select id="free-location">${FoilLocations.sites.map(l=>`<option value="${l.id}" ${l.id===currentLocation.id?'selected':''}>${l.name}</option>`).join('')}</select></label>`:''}<div class="weather-presets" aria-label="Weather presets">${weatherPresets.map((p,i)=>`<button type="button" id="weather-preset-${i}" data-weather-preset="${i}" aria-pressed="false"><b>${p.name}</b><small>${p.detail}</small></button>`).join('')}</div>
 <div class="condition-grid">${conditionFields.map(f=>`<label class="condition-field" for="condition-${f.key}"><span><b>${f.label}</b><output id="condition-${f.key}-value" for="condition-${f.key}"></output></span><input id="condition-${f.key}" type="range" min="${f.min}" max="${f.max}" step="${f.step}" aria-describedby="condition-${f.key}-hint"><small id="condition-${f.key}-hint">${f.hint}</small></label>`).join('')}</div>
 <label class="traffic-setting" for="other-foilers"><span><b>Other foilers</b><output id="other-foilers-value">${otherFoilers}</output></span><input id="other-foilers" type="range" min="0" max="25" step="1" value="${otherFoilers}"><small>Quiet water at 0, or share the bay with up to 25 riders.</small></label><label class="traffic-setting" for="foiler-experience"><span><b>Foiler experience</b><output id="foiler-experience-value">${Math.round((1-expertRatio)*100)}% beginners · ${Math.round(expertRatio*100)}% experts</output></span><input id="foiler-experience" type="range" min="0" max="100" step="5" value="${Math.round(expertRatio*100)}"><small>Beginners taxi, attempt flight, and fall; experts pump and stay on foil.</small></label><div class="conditions-advice" id="conditions-advice" role="status"></div>
 ${launch?`<div class="settings"><label>Control feel<select id="free-assist"><option value="yes" ${progress.assist?'selected':''}>Coached · stable speed trim</option><option value="no" ${!progress.assist?'selected':''}>Direct · more responsive</option></select></label></div>`:''}
 <p class="note">${launch?'Time on foil earns points.':'Changes apply when you resume; your position, score and lesson progress stay with you.'} Wind direction is where the breeze comes <em>from</em>; wave direction is where the crests travel <em>toward</em>.</p>
 <div class="conditions-actions"><button class="primary-button" id="conditions-apply">${launch?'Launch into the bay':'Apply & resume'} <span>→</span></button><button class="text-button" id="conditions-cancel">${launch?'Back to the lesson chart':'Cancel'}</button></div>`,true);
 function refresh(fill=false){
  const heightMax=Math.min(1.2,draft.waveLength*.14);$('condition-swell').max=heightMax.toFixed(2);if(draft.swell*2>heightMax){draft.swell=heightMax/2;$('condition-swell').value=heightMax;}

  for(const f of conditionFields){let n=draft[f.key]*f.scale;if(f.unit==='bearing')n=(n+360)%360;const input=$('condition-'+f.key);if(fill)input.value=n;
   const text=f.unit==='bearing'?['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'][Math.round(n/22.5)%16]+' · '+Number(n.toFixed(1))+'°':f.unit==='m'?n.toFixed(2)+' m':f.unit==='length'?Math.round(n)+' m · '+(2*Math.PI/1.35*Math.sqrt(n/45)).toFixed(1)+' s':f.unit==='kn'?n.toFixed(1)+' kn':Math.round(n)+'%';
   $('condition-'+f.key+'-value').value=text;input.setAttribute('aria-valuetext',text);
  }
  $('conditions-advice').textContent=draft.wind<5.5?'Light air: expect little takeoff power. Enjoy a swim, or raise the wind for foiling.':draft.wind>10.8||draft.swell>.32||draft.gust>.25?'A lively practice day. Start across the wind, leave extra mast clearance, and use small body corrections.':'A friendly practice breeze. Start across the wind with about 65–70% wing power, then add a little back-foot pressure.';
 }
 for(const f of conditionFields)$('condition-'+f.key).oninput=e=>{draft[f.key]=Number(e.target.value)/f.scale;document.querySelectorAll('[data-weather-preset]').forEach(b=>b.setAttribute('aria-pressed','false'));refresh();};
 if(launch)$('free-location').onchange=e=>{draft.windFrom=FoilLocations.sites.find(l=>l.id===e.target.value).windFrom??0;draft.waveDirection=wrap(draft.windFrom+Math.PI);refresh(true);};
 document.querySelectorAll('[data-weather-preset]').forEach(b=>b.onclick=()=>{const {name,detail,...preset}=weatherPresets[Number(b.dataset.weatherPreset)];draft={...draft,...preset,waveDirection:wrap(draft.windFrom+preset.waveDirection)};document.querySelectorAll('[data-weather-preset]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));refresh(true);});
 $('other-foilers').oninput=e=>{otherFoilers=Number(e.target.value);$('other-foilers-value').value=otherFoilers;};
 $('foiler-experience').oninput=e=>{expertRatio=Number(e.target.value)/100;$('foiler-experience-value').value=Math.round((1-expertRatio)*100)+'% beginners · '+Math.round(expertRatio*100)+'% experts';};
 $('conditions-apply').onclick=()=>{progress.expertRatio=expertRatio;progress.otherFoilers=otherFoilers;traffic.setCount(otherFoilers);saveProgress();if(launch){progress.assist=$('free-assist').value==='yes';saveProgress();if($('free-location').value!==currentLocation.id){travel($('free-location').value,{lesson:0,free:true,conditions:draft});return;}startLesson(0,{free:true,conditions:draft});}else{session.setConditions(draft);closeModal();updateUI();toast('Conditions updated. Check the compass for the new breeze.',4);}};
 $('conditions-cancel').onclick=()=>launch?lessonChart():closeModal();refresh(true);
}
function travel(id,options={}){
 if(started)storeRecord();const url=new URL(location.href);url.searchParams.set('location',id);for(const k of ['lesson','free','conditions','screen'])url.searchParams.delete(k);
 if(options.lesson!==undefined){url.searchParams.set('lesson',LESSONS[options.lesson].id);if(options.free)url.searchParams.set('free','1');if(options.conditions)url.searchParams.set('conditions',JSON.stringify(options.conditions));}
 else url.searchParams.set('screen',options.screen||'chart');
 if(changingLocation)return;changingLocation=true;releaseControls();paused=true;const saved=JSON.parse(JSON.stringify({...progress,version:2}));
 $('modal').classList.add('hidden');$('loading').textContent='Opening '+(FoilLocations.sites.find(s=>s.id===id)?.name||'the bay')+'…';$('loading').classList.remove('hidden');
 // Paint the loading message before building terrain, and free the old GPU
 // buffers / AudioContext / event handlers before allocating the next scene.
 requestAnimationFrame(()=>setTimeout(()=>{
  disposeCurrent?.();if(window.foilTest)window.foilTest=null;
  document.getElementById('game').outerHTML=initialGame;document.getElementById('modal').outerHTML=initialModal;document.getElementById('modal').classList.add('hidden');
  try{history.replaceState(null,'',url.href);}catch{} // file previews may disallow URL changes
  try{FoilWorld.activate(id);launchSite(url.searchParams,saved);}catch(error){const f=document.getElementById('fallback');document.getElementById('loading').classList.add('hidden');f.classList.remove('hidden');f.innerHTML='<h1>This bay could not open.</h1><p>Your course records are saved. Try Academy Bay or reload the page.</p><p id="load-detail"></p><button id="load-academy">Open Academy Bay</button>';document.getElementById('load-detail').textContent=error.message;document.getElementById('load-academy').onclick=()=>{FoilWorld.activate('academy');document.getElementById('game').outerHTML=initialGame;document.getElementById('modal').outerHTML=initialModal;launchSite(new URLSearchParams(),saved);};console.error(error);}finally{changingLocation=false;}
 },30));
}
function locationMenu(back='chart'){
 view='locations';modal(`<span class="eyebrow">FIND YOUR WATER</span><h2 id="modal-title">Five places to fly.</h2><p>Choose a setting for every course and Free Foiling.${started?' Traveling starts a fresh attempt; your records stay saved.':''}</p><div class="location-grid">${FoilLocations.sites.map(l=>`<button class="location-option ${l.id===currentLocation.id?'active':''}" data-location="${l.id}" aria-pressed="${l.id===currentLocation.id}"><small>${l.subtitle}</small><strong>${l.name}</strong><span>${l.description}</span>${l.id===currentLocation.id?'<em>YOU ARE HERE</em>':''}</button>`).join('')}</div><p class="note">Real shore outlines and landmark positions from <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a>. Terrain uses USGS elevation data; buildings and underwater depths are simplified. Crissy uses the East Beach launch on the bay’s south shore.</p><button class="secondary-button" id="locations-back">Back</button>`,true);
 document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{if(b.dataset.location===currentLocation.id){back==='play'?closeModal():back==='intro'?welcome():lessonChart();return;}travel(b.dataset.location,back==='play'?{lesson:session.lesson,free:session.free}:{screen:back});});
 $('locations-back').onclick=()=>back==='play'?closeModal():back==='intro'?welcome():lessonChart();
}

function freeSetup(){conditionsMenu(true);}
function pauseGame(){if(!started)return;if(paused&&view==='pause'){closeModal();return;}if(paused)return;view='pause';storeRecord();modal(`<span class="eyebrow">A MOMENT ON THE WATER</span><h2 id="modal-title">Take a breath.</h2><p>Your board, the breeze, and your flight timer are paused.</p><div class="results"><div><b>${session.stats.flightTime.toFixed(1)}s</b><small>TOTAL FLIGHT</small></div><div><b>${session.stats.bestFlight.toFixed(1)}s</b><small>LONGEST RUN</small></div><div><b>${Math.floor(session.score)}</b><small>POINTS</small></div></div><button class="primary-button" id="resume">Back to the water <span>→</span></button><button class="secondary-button" id="pause-conditions">Wind, waves & weather</button><button class="secondary-button" id="pause-location">Location · ${currentLocation.name}</button><button class="secondary-button" id="pause-lessons">Foil Academy courses</button><button class="secondary-button" id="pause-return">Return to launch · keep score</button><button class="secondary-button" id="pause-reset">Restart this session</button><button class="text-button" id="pause-guide">Controls & field guide</button>`);$('resume').onclick=closeModal;$('pause-conditions').onclick=()=>conditionsMenu();$('pause-lessons').onclick=lessonChart;$('pause-location').onclick=()=>locationMenu('play');$('pause-return').onclick=()=>{session.recover();$('trim').value=0;closeModal();};$('pause-reset').onclick=()=>startLesson(session.lesson,{free:session.free,conditions:session.config});$('pause-guide').onclick=guide;}
function storeRecord(){progress.bestFlight=Math.max(Number(progress.bestFlight)||0,session.stats.bestFlight);progress.bestScore=Math.max(Number(progress.bestScore)||0,Math.floor(session.score));saveProgress();}
function finishLesson(){storeRecord();const stars=session.stats.crashes===0?3:session.stats.crashes<=2?2:1,old=progress.lessons[session.config.id];progress.lessons[session.config.id]={stars:Math.max(old?.stars||0,stars),score:Math.max(old?.score||0,Math.floor(session.score))};saveProgress();view='complete';modal(`<span class="eyebrow">${session.lesson===LESSONS.length-1?'FOIL ACADEMY · COMPLETE':'A NEW SKILL, EARNED'}</span><h2 id="modal-title">${session.lesson===LESSONS.length-1?'The bay is yours.':session.config.name+'.'}</h2><div class="award-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>${session.config.learn}</p><div class="results"><div><b>${session.stats.flightTime.toFixed(1)}s</b><small>TIME ON FOIL</small></div><div><b>${session.stats.bestFlight.toFixed(1)}s</b><small>LONGEST FLIGHT</small></div><div><b>${Math.floor(session.score)}</b><small>POINTS</small></div></div><button id="next-lesson" class="primary-button">${session.lesson<LESSONS.length-1?'Next: '+LESSONS[session.lesson+1].name:'Explore free foiling'} <span>→</span></button><button id="keep-riding" class="secondary-button">Keep practicing here</button><button id="result-chart" class="text-button">Open lesson chart</button><p class="note">Three stars: no falls · Two stars: up to two falls · Every completed lesson earns a star.</p>`);$('next-lesson').onclick=()=>session.lesson<LESSONS.length-1?startLesson(session.lesson+1):freeSetup();$('keep-riding').onclick=()=>{session.free=true;closeModal();};$('result-chart').onclick=lessonChart;}
function guide(){view='guide';modal(`<span class="eyebrow">THE FIELD GUIDE</span><h2 id="modal-title">Wind in your hands.<br>Balance in your feet.</h2><div class="field-grid"><div><b>1 · Catch the wind</b><p>Tap Stand up. Pull the wing pad down toward 65% power. Aim across the wind on the compass. More trim is not always more power: over 85% can stall the wing.</p></div><div><b>2 · Find the foil</b><p>Use the left pad: down adds back-foot pressure and raises the nose; up adds front-foot pressure and lowers it. Build speed first, then briefly press back. In coached mode, center the pad as you rise; speed trim helps settle the pitch. Use small corrections for the green 25–60 cm band.</p></div><div><b>3 · Carve a line</b><p>Drag the left pad sideways to bank and steer. Green marks easy takeoff reaches near 90°; red is the upwind no-go zone. Blue is your board; the thin gold arrow is apparent wind coming toward you.</p></div><div><b>4 · Make a pump</b><p>Hold PUMP briefly to compress. Release when its marker is green, then recover. A timed stroke adds speed; rapid tapping drains energy.</p></div><div><b>5 · Jibe / gybe</b><p>Build speed, then turn away from the wind toward 180°. Unload the wing until the wing pad says Wing light, transfer hands around 180°, complete the turn and sheet in. Stay on foil for the maneuver bonus.</p></div><div><b>6 · Tack</b><p>Build speed, then turn toward the wind at 0°. Ease and raise the wing, transfer around 0°, and turn through the no-go zone. Power up on the opposite reach.</p></div></div><p><b>Conditions:</b> Open Conditions in the top bar to change wind speed and direction, gusts, wave height, spacing, choppiness, wave direction, cloud cover and sunlight. Lively ripples gives you small, quick, varied waves; rolling swell gives you long, slower waves. Apply resumes your current session; Cancel keeps the previous weather. The compass shows where the wind comes from.</p><p><b>Power loss:</b> The number under the compass is true wind, not wing drive. The wing panel shows when you are pointing into wind, oversheeting, changing sides, or in a lull. After a fall, power resets to zero: stand, then sheet in again.</p><p><b>Explore:</b> Jump off anywhere with E or Jump off. Swim while towing the board, or use Space / Leave board to swim freely. Low beaches and the castle landing let you walk ashore automatically. Follow the stone path to four discoveries, then swim back and choose Climb aboard within 3 m. Your board stays in the water.</p><p><b>Horseback exploration:</b> Find Clover or Willow near the shore parking area. Walk close and press H / Ride. The right joystick or arrow keys move and turn; push gently to walk, farther to trot or canter, fully forward to gallop. Release to stop, then H or E dismounts. The left pad looks around. Your board stays where you left it.</p><p><b>Shallows:</b> UNDER FOIL is clearance beneath the lowest part of the foil, including a banked wingtip. Turn away when the warning appears. The submerged foil can hit bottom before the board reaches land.</p><p><b>Footwork and gliding:</b> F / Switch feet changes the front foot independently of moving the wing across the upper arc. Center the pad through the step. G / Flag wing holds the wing by the leading edge and removes its drive; G again powers it. Follow wave travel for wave-riding credit, or head downwind for a continuous glide. Space still pumps the foil while flagged.</p><p><b>Aerial controls:</b> Fly level above 10 knots in deep water. Hold J / Pop for 0.4–0.7 s and release. In the air the same pad changes function: A/D or left/right spins, W/S or front/back flips. Watch the angle readout and center to brake. Half turns need a wing transfer; ease with the wing pad or ↑, then move across the upper arc or use ← / →. Credit requires the foil to clear, a level landing and a one-second ride-away. Frontside turns toward the chest: right with left foot forward, left with right foot forward. Backside is the opposite. These are simplified game drills, not complete real-world trick instruction.</p><p><b>Laptop:</b> A/D steer · W/S front/back pressure · ↑ ease / ↓ sheet in · ←/→ wing angle · Enter stand · Space hold/release pump · F switch feet · G flag wing · J hold/release pop · E jump off · R return to launch · Esc pause. On foot or swimming: arrow keys or W/S move, A/D turn. On land, the left pad looks around and Center view resets it. Space tow/leave board; Enter climb aboard nearby.</p><p><b>Touch:</b> left thumb controls body and steering; right thumb slides around the upper wing arc and pulls down to sheet in; both settings stay where you leave them. The action buttons work with simultaneous touches. On land, the right joystick moves and turns while the left pad looks around. All sailing actions also have keyboard controls.</p><p class="note">A forgiving model of the key relationships, not a calibrated equipment simulator. The game simplifies wing handling, footwork and freestyle; it does not teach every real-world movement.</p><p class="guide-links">Learning references: <a href="https://www.rya.org.uk/training/wing-courses/" target="_blank" rel="noopener">RYA wing progression</a> · <a href="https://ozonekites.com/learn-to-wingfoil-video-series/" target="_blank" rel="noopener">Ozone learning series</a></p><button class="primary-button" id="guide-close">${started?'Back to the water':'Back to the start'} <span>→</span></button>`,true);$('guide-close').onclick=()=>started?closeModal():welcome();}
function toast(text,duration=3){$('toast').textContent=text;$('toast').classList.remove('hidden');toastUntil=performance.now()+duration*1000;}
function releaseControls(){walkPointer=null;walkInput={steer:0,balance:0};$('walk-knob').style.transform='translate(0px,0px)';keys.clear();walkPointers.clear();document.querySelectorAll('[data-walk]').forEach(b=>b.classList.remove('active'));pumpPointer=null;popPointer=null;wingPointer=null;joystickInput={steer:0,balance:0};activePointer=null;$('joy-knob').style.transform='translate(0px,0px)';if(session){session.controls.steer=0;session.controls.balance=0;session.pumpHeld=false;session.pumpCharge=0;session.popHeld=false;session.popCharge=0;}}
$('conditions').onclick=()=>conditionsMenu(!started);$('home').onclick=()=>started?lessonChart():welcome();$('lesson-list').onclick=lessonChart;$('help').onclick=guide;$('pause').onclick=pauseGame;$('sound').onclick=()=>{audio.enabled=!audio.enabled;progress.sound=audio.enabled;audio.unlock();saveProgress();updateUI();};$('stand').onclick=()=>{if(paused)return;audio.unlock();session.stand();updateUI();};$('reset').onclick=()=>{if(!paused){storeRecord();session.recover();$('trim').value=0;releaseControls();toast('Back in deep water. Stand up when you’re ready.');}};
$('dismount').onclick=()=>{if(!paused){session.dismount();handleEvents();updateUI();}};
$('trim').addEventListener('input',()=>{if(paused)return;audio.unlock();session.controls.trim=Number($('trim').value)/100;});
function updateWingPad(e){const svg=$('wing-pad').querySelector('svg'),point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),value=FoilWingControl.read(point.x,point.y,session.wingTarget);session.setWingPosition(value.angle);session.controls.trim=value.power;paintWingPad();}
