function handleEvents(){for(const event of session.drain()){audio.event(event.type);if(event.type==='horse-mount'||event.type==='horse-dismount'){releaseControls();lookYaw=0;lookPitch=.30;cameraReady=false;toast(event.type==='horse-mount'?'Meet '+event.name+'. Right pad or arrow keys ride; push farther to go faster.':'Back on foot. '+event.name+' will wait here.',5);}if(event.type==='pop'){splash(24);toast('Airborne. Steer to rotate; center the pad before landing.',3);}if(event.type==='airlanding'){splash(28);environment.impact(session.x,session.z,session.time,.45);audio.splash(.45);releaseControls();toast('Landing made. Hold level for one second.',2);}if(event.type==='skill'){toast(event.label+' · +'+event.points+' points',4);audio.event('maneuver');}if(event.type==='flag')toast(event.flagged?'Wing flagged. Follow the wave, or pump to keep gliding.':'Wing powered. Ease in and find your reach.',4);if(event.type==='hint')toast(event.text,4);if(['dismount','board','ashore','swim','splashdown'].includes(event.type)){releaseControls();lookYaw=0;lookPitch=.34;cameraReady=false;$('trim').value=0;if(event.type==='dismount'){splash(22);environment.impact(session.x,session.z,session.time,.5);audio.splash(.5);toast('Jumped off. Move with the body pad; Space or Tow / Leave board changes towing.',6);}if(event.type==='splashdown'){const strength=clamp((event.speed||4)/7,.45,1.5);splash(Math.round(65*strength),{x:event.x,z:event.z},false,strength);environment.impact(session.x,session.z,session.time,strength);audio.splash(strength);toast('In the water. Swim to the board and press Enter / Climb aboard when you are ready.',6);}if(event.type==='board')fallenWing=null;if(event.type==='board')toast('Back aboard. Stand, then sheet in to get going.',5);if(event.type==='ashore')toast('Ashore. Arrow keys / WASD or the right pad move; the left pad looks around.',6);}if(event.type==='discovery'){lastDiscovery=event.name+'. '+event.text;toast(event.name+' · +75 exploration points',6);audio.event('gate');}if(event.type==='takeoff'){splash(16);toast('On foil. Ease forward and find the quiet.',3);}if(event.type==='fall'){fallenWing={position:wing.getWorldPosition(new THREE.Vector3()),rotation:wing.getWorldQuaternion(new THREE.Quaternion())};releaseControls();$('trim').value=0;toast(event.reason,6);}if(event.type==='ready')toast('Ready again. Stand up and catch the wind.',4);if(event.type==='landing'){splash(12);toast('Soft touchdown. Nicely controlled.',3);}if(event.type==='maneuver')toast((event.kind==='jibes'?'Foiling jibe · +250':'Foiling tack · +350')+' points',4);if(event.type==='gate')toast('Clean through the gate · +150 points',3);if(event.type==='complete')finishLesson();}}
